      "content": "**定义与核心概念**\\n分类是研究化学的基本方法。物质按组成可分为混合物与纯净物:混合物由两种或两种以上物质组成,无固定熔沸点,如空气、盐酸、石油;纯净物由一种物质组成,有固定熔沸点,如冰水共存物、胆矾(CuSO4·5H2O)、纯碱(Na2CO3)。纯净物再分为单质与化合物:由同种元素组成的纯净物是单质(金属、非金属、稀有气体),由不同种元素组成的纯净物是化合物。常用树状分类法逐层细化,也用交叉分类法按不同标准归类同一物质,如 Na2CO3 既是钠盐又是碳酸盐。\\n**核心公式/规律**\\n各类物质之间存在转化主线:金属→碱性氧化物→碱→盐,如 Na→Na2O→NaOH→NaCl;非金属→酸性氧化物→酸→盐,如 C→CO2→H2CO3→CaCO3。实现转化的核心反应有:碱性氧化物与水(仅 K2O、Na2O、CaO 等)或与酸反应、酸性氧化物与水或与碱反应、酸与碱中和、盐之间的复分解、活泼金属置换不活泼金属等。代表反应:$\\mathrm{Na_{2}O+H_{2}O=2NaOH}$、$\\mathrm{CO_{2}+2NaOH=Na_{2}CO_{3}+H_{2}O}$、$\\mathrm{NaOH+HCl=NaCl+H_{2}O}$。\\n**方法与思路**\\n判断物质类别先看组成:几种物质→混合物;一种物质再看是否同种元素→单质或化合物。分析一步转化题要抓\"类别通性\":碱性氧化物与酸生成盐和水,酸性氧化物与碱生成盐和水;同时警惕不能一步完成的情况,如 Cu→Cu(OH)2 不行(CuO 不溶于水),需 Cu→CuO→CuSO4→Cu(OH)2 两步以上;又如 CO2 制 Na2CO3 需与 NaOH 反应而非与水一步。\\n**常考题型与考法**\\n选择题考物质归类:盐酸、漂白粉、氨水、碱石灰是混合物;液氯、冰水、胆矾、纯碱是纯净物;Na2CO3 是盐不是碱。\"一步转化能否实现\"题:Cu→Cu(OH)2、Fe→FeCl3(直接与 Cl2 点燃可行)、S→SO3(不行,只能 SO2)等。转化网络题以初中四大反应衔接,常与金属活动性、复分解条件联考。\\n**易错提示**\\n由同种元素组成的物质不一定是纯净物(O2 与 O3 混合);含氧元素的化合物不一定是氧化物(高锰酸钾是盐);溶液、悬浊液都是混合物;结晶水合物(胆矾、绿矾)是组成固定的纯净物;纯碱、烧碱、苛性钠名称易混,烧碱是 NaOH、纯碱是 Na2CO3。",
