      "content": "**定义与核心概念**\\n氧化物是由两种元素组成且其中一种是氧元素的化合物。按化学性质分为四类:碱性氧化物:能与酸反应生成盐和水的氧化物,如 Na2O、CaO、Fe2O3、CuO,多为金属氧化物;酸性氧化物:能与碱反应生成盐和水的氧化物,如 CO2、SO2、SO3、SiO2,多为非金属氧化物;两性氧化物:既能与酸又能与强碱反应生成盐和水,典型是 Al2O3;不成盐氧化物:不能与酸或碱直接反应生成盐,如 CO、NO。分类依据是化学性质而非元素组成:Mn2O7 是金属氧化物却是酸性氧化物。\\n**核心公式/规律**\\n碱性氧化物的通性:与酸反应生成盐和水,如 $\\mathrm{CaO+2HCl=CaCl_{2}+H_{2}O}$、$\\mathrm{Fe_{2}O_{3}+6HCl=2FeCl_{3}+3H_{2}O}$;活泼金属氧化物能与水化合生成碱:$\\mathrm{Na_{2}O+H_{2}O=2NaOH}$。酸性氧化物通性:与碱反应生成盐和水,如 $\\mathrm{CO_{2}+2NaOH=Na_{2}CO_{3}+H_{2}O}$;多数能与水化合生成酸:CO2、SO2、SO3 分别生成 H2CO3、H2SO3、H2SO4。碱性氧化物与酸性氧化物可化合生成盐:$\\mathrm{CaO+CO_{2}=CaCO_{3}}$。\\n**方法与思路**\\n判类别用\"性质试金石\":能与酸反应生成盐和水→碱性氧化物;能与碱反应生成盐和水→酸性氧化物;两者都行→两性氧化物(Al2O3);都不行→不成盐氧化物(CO、NO)。注意三组易错:CuO、Fe2O3 是碱性氧化物但不与水反应,不能直接用水制碱;SiO2 是酸性氧化物但不溶于水、不与水直接化合;Na2O2 与水反应还放出氧气,不属于碱性氧化物。NO2 与碱反应发生氧化还原生成硝酸盐和亚硝酸盐,也不是酸性氧化物。\\n**常考题型与考法**\\n选择题:归类判断(CO、NO 不成盐;Na2O2 是过氧化物;Al2O3 两性;SiO2 特殊酸性氧化物);\"下列氧化物能与水直接化合生成碱/酸\"类;除杂与转化(CO2 中除 CO 用灼热 CuO,CO 中除 CO2 用 NaOH 溶液);酸性氧化物与碱的少量过量反应书写(见离子反应节点);与元素化合物结合(Fe2O3 除锈、SO2 被碱吸收、SiO2 与 HF 反应见硅节点)。\\n**易错提示**\\n金属氧化物不一定是碱性氧化物(Al2O3 两性、Mn2O7 酸性);非金属氧化物不一定是酸性氧化物(CO、NO);酸性氧化物不一定溶于水(SiO2),碱性氧化物不一定溶于水(CuO、Fe2O3);过氧化物不是碱性氧化物;判断类别必须以能否与酸碱反应生成盐和水为准,不能只看元素组成。",
