      "content": "**定义与核心概念**\\n酸是电离时产生的阳离子全部是 H+ 的化合物(如 HCl、H2SO4、CH3COOH);碱是电离时产生的阴离子全部是 OH- 的化合物(如 NaOH、Ca(OH)2、NH3·H2O);盐由金属阳离子(或 NH4+)与酸根阴离子组成(如 NaCl、Na2CO3、NH4Cl)。注意纯碱 Na2CO3 是盐;NH3·H2O 是碱但 NH3 不是碱。酸碱指示剂:紫色石蕊遇酸变红、遇碱变蓝;无色酚酞遇碱变红、遇酸不变色。\\n**核心公式/规律**\\n酸的通性(本质是 H+):与指示剂;与活动性顺序 H 前金属置换放 H2;与碱性氧化物生成盐和水;与碱中和生成盐和水;与某些盐反应。硝酸与浓硫酸是氧化性酸,与金属反应不放 H2。碱的通性(本质是 OH-):与指示剂;与酸性氧化物生成盐和水;与酸中和;与某些盐反应(碱与盐反应要求两者均可溶)。盐的通性:与活泼金属置换(Fe+CuSO4)、与酸、与碱、与盐复分解。代表反应:$\\mathrm{NaOH+HCl=NaCl+H_{2}O}$、$\\mathrm{2NaOH+CuSO_{4}=Cu(OH)_{2}\\downarrow+Na_{2}SO_{4}}$、$\\mathrm{Fe+CuSO_{4}=FeSO_{4}+Cu}$。\\n**方法与思路**\\n记住盐的溶解性口诀:钾钠铵硝皆可溶;盐酸盐中 AgCl 不溶;硫酸盐中 BaSO4 不溶(CaSO4、Ag2SO4 微溶);碳酸盐中除钾钠铵外多数不溶;碱中 KOH、NaOH、Ba(OH)2 可溶,Ca(OH)2 微溶,其余多数不溶。判断反应能否发生:先对类别通性,再看复分解条件或金属活动性,不可只凭\"两种物质能反应\"臆断。\\n**常考题型与考法**\\n鉴别题:用指示剂或选择与目标离子产生特征现象的试剂;判断\"酸的通性\"与浓硫酸个性(吸水、脱水、强氧化)区分;中和反应与 pH 变化;溶液是否变质的检验(如 NaOH 变质为 Na2CO3,加过量 CaCl2 检验 CO32-);判断给定酸、碱、盐之间反应能否发生并写方程式。\\n**易错提示**\\nNa2CO3 俗称纯碱但其水溶液显碱性的原因是 CO32- 与水电离出的 H+ 结合(盐类水解),它本身是盐;NaHSO4 电离出的阳离子含 H+ 但不属于酸(还有 Na+),故酸必须\"全部是 H+\";Cu(OH)2 难溶仍是碱;碱石灰是 CaO 与 NaOH 的混合物,不是碱;氨水是混合物,其溶质 NH3 不是碱而 NH3·H2O 是碱。",
