      "content": "**定义与核心概念**\\n物质由微观粒子构成,构成粒子有三种:分子(水由水分子构成、H2 由氢分子构成)、原子(金属、稀有气体、金刚石、晶体硅等由原子直接构成)、离子(NaCl 由 Na+ 与 Cl- 构成)。原子由原子核与核外电子构成,原子核含质子和中子:质子数=核电荷数=原子序数=核外电子数(中性原子),质子数决定元素种类,中子数影响原子的质量与核素种类。元素是具有相同质子数的一类原子的总称,是宏观概念,只论种类不讲个数。同位素:质子数相同而中子数不同的同种元素的不同原子(核素),如氢的三种核素氕、氘、氚,化学性质几乎相同;应用如碳-14 考古断代、铀-235 核燃料、放射性同位素示踪。\\n**核心公式/规律**\\n原子内数量关系:质子数+中子数=质量数,表示核素时质量数写在左上角、质子数写在左下角,如 $\\mathrm{^{1}_{1}H}$、$\\mathrm{^{2}_{1}H}$、$\\mathrm{^{3}_{1}H}$ 与 $\\mathrm{^{35}_{17}Cl}$、$\\mathrm{^{37}_{17}Cl}$。相对原子质量以碳-12 原子质量的 1/12 为基准;元素的相对原子质量等于各天然核素的相对原子质量乘丰度之和,故氯元素相对原子质量约为 35.5。化学式的相对分子质量等于各元素相对原子质量之和。\\n**方法与思路**\\n描述\"某物质由什么构成\"时先判粒子类型:金属、多数非金属单质(金刚石、硅)由原子构成;稀有气体由原子构成;共价化合物(水、CO2、HCl)由分子构成;离子化合物(活泼金属与活泼非金属形成的 NaCl、CaO,以及 NaOH 等)由离子构成。常用等电子微粒作推断突破口:10 电子微粒有 Ne、Na+、Mg2+、Al3+、F-、O2-、H2O、NH3、CH4、HF 等。\\n**常考题型与考法**\\n选择题:NaCl 由离子构成而非\"氯化钠分子\";计算原子中各粒子数(质子 17、质量数 37 的氯原子中子数 20);同位素判断(O2 与 O3 是同素异形体不是同位素;1H、2H、3H 互为同位素);由同位素丰度求元素相对原子质量;物质由分子/原子/离子构成的归类。\\n**易错提示**\\n不是所有原子核都有中子(氕无中子);同位素属于同种元素、化学性质几乎相同,物理性质有差异;分子是保持物质化学性质的最小微粒只对由分子构成的物质成立,化学变化中分子可分、原子不可再分;元素论种类不讲个数(水由氢元素和氧元素组成,水分子含两个氢原子);元素符号与化学式的书写规范属\"化学用语\"板块。",
