      "content": "**定义与核心概念**\\n按反应形式,化学反应分为四种基本类型:化合反应(多变一,如 $\\mathrm{CaO+H_{2}O=Ca(OH)_{2}}$);分解反应(一变多,如 $\\mathrm{CaCO_{3}\\xrightarrow{高温}CaO+CO_{2}\\uparrow}$);置换反应(一种单质与一种化合物反应生成另一种单质与另一种化合物,如 $\\mathrm{Zn+H_{2}SO_{4}=ZnSO_{4}+H_{2}\\uparrow}$);复分解反应(两种化合物互相交换成分,如 $\\mathrm{NaOH+HCl=NaCl+H_{2}O}$)。四大基本类型按反应形式分类,与是否氧化还原是两套标准:置换反应一定是氧化还原反应,复分解反应一定不是,化合与分解反应可能是不一定(如 CaO+H2O 不是氧化还原,2Na+Cl2 点燃 2NaCl 是)。\\n**核心公式/规律**\\n金属活动性顺序:K Ca Na Mg Al Zn Fe Sn Pb (H) Cu Hg Ag Pt Au,位置越靠前活动性越强。应用:排在 H 前的金属能与稀盐酸、稀硫酸等非氧化性酸反应放出 H2(硝酸、浓硫酸是氧化性酸除外);排在前面的金属能把后面的金属从其盐溶液中置换出来,但 K、Ca、Na 太活泼,遇盐溶液先与水反应,不能置换出盐中的金属。复分解反应发生条件(生成物角度):生成物中有沉淀、气体或水;反应物角度:盐与盐、碱与盐反应时一般要求两者均可溶(酸与盐、酸与碱反应时酸须可溶)。复分解的实质是溶液中某些离子浓度减小(详见离子反应节点),反应前后各元素化合价不变。\\n**方法与思路**\\n判断反应类型:先写清反应物与生成物的类别和数目(一种变多种、两种交换成分等),再判断是否氧化还原(看有无元素化合价变化)。设计物质转化路线时按目标产物选择反应类型;判断复分解能否发生先查溶解性口诀,再看能否生成沉淀/气体/水。\\n**常考题型与考法**\\n选择题:\"下列反应属于置换反应/复分解反应的是\";\"不属于四大基本类型的反应\"(如 $\\mathrm{CO+CuO\\xrightarrow{\\Delta}Cu+CO_{2}}$ 反应物都是化合物、不属于四大类型却是氧化还原;CH4 燃烧);复分解发生条件判断(FeCl3 与 NaOH 溶液、NaCl 与 KNO3 不反应);金属活动性应用(Zn 置换 FeSO4 中的 Fe,Cu 不能与 FeSO4 反应)。\\n**易错提示**\\n分解反应产物可能含单质也可能都是化合物(如 CaCO3 分解产物全是化合物);化合反应不一定放热且不一定需要加热;复分解中化合价不变,若写方程式出现价态变化即判断有误;CO 还原 CuO、Fe2O3+3CO 高温都不是置换反应(反应物无单质);金属与盐溶液反应须满足\"前换后、盐可溶\"。",
