      "content": "**定义与核心概念**\\n元素周期表把元素按原子序数递增排列,并按核外电子排布规律编排:电子层数相同的元素排在同一横行(周期),最外层电子数相同的元素按电子层数递增排成纵列(族)。周期表共 7 个横行即 7 个周期(第 1~3 周期为短周期,第 4~6 为长周期,第 7 周期现已排满),周期序数等于电子层数。18 个纵列组成 16 个族:7 个主族(ⅠA~ⅦA)、7 个副族(ⅠB~ⅦB)、第Ⅷ族(第 8、9、10 三个纵列)和 0 族(稀有气体)。\\n**核心公式/规律**\\n原子序数=核电荷数=质子数=核外电子数。主族序数=最外层电子数,如 Na 是第三周期ⅠA 族,最外层 1 个电子;周期序数=电子层数,Na 有 3 个电子层。族序数等于最外层电子数只适用于主族元素。元素在周期表中的\"格\"包含原子序数、元素符号、元素名称与相对原子质量四项信息。\\n**方法与思路**\\n位置与结构互推:由位置(周期、族)推结构,先定电子层数再定最外层电子数,再按各层电子数排布(K 层最多 2、L 层最多 8);由原子序数推位置:如 17 号元素有 3 个电子层、最外层 7 个电子,位于第三周期ⅦA 族(氯),短周期元素(1~18 号)的电子排布是推断基础。金属与非金属分界:周期表右上方为阶梯线,分界线附近元素(B、Si、Ge、As 等)既显金属性又显非金属性,Si、Ge 是优良半导体材料;副族与第Ⅷ族为过渡元素,全部是金属,许多可作催化剂;0 族为稀有气体。\\n**常考题型与考法**\\n选择题:周期表\"格\"信息判读;由原子序数定位置(如 35 号元素位于第四周期ⅦA 族);周期、族概念辨析(\"最外层电子数相同的元素一定同族\"是错的,He 与 Mg 最外层都是 2 个电子但分别在 0 族与ⅡA 族);由位置片段判断相邻元素的原子序数差(同周期相邻、同主族相差 8 或 18 等);元素推断题的第一步定位(见位置-结构-性质节点)。\\n**易错提示**\\n第Ⅷ族占 3 个纵列,故 18 纵列只有 16 个族;0 族不是主族(He 最外层 2 个电子,其余最外层 8 个);副族及第Ⅷ族元素最外层电子数不等于族序数;原子序数与相对原子质量不同(前者是质子数);\"族\"的罗马数字写法与主副族标识(ⅠA、ⅦA、ⅠB)要分清;最外层电子数相同的元素未必同族。",
