      "content": "**定义与核心概念**\\n元素的性质随原子序数递增而呈周期性变化的规律称为元素周期律,其根本原因是核外电子排布(最外层电子数)的周期性变化。周期性表现于:原子半径、主要化合价、金属性与非金属性、气态氢化物的稳定性、最高价氧化物对应水化物的酸碱性等。\\n**核心公式/规律**\\n同周期从左到右:原子半径减小(电子层数相同、核电荷数增大、对核外电子引力增强);金属性减弱、非金属性增强;最高价氧化物对应水化物碱性减弱、酸性增强(如碱性 NaOH 强于 Mg(OH)2、Al(OH)3 两性);气态氢化物稳定性增强(如稳定性 HCl>H2S>PH3);主要化合价:最高正价=主族序数(O、F 除外),最低负价=主族序数-8(金属无负价),如 Cl 最高+7、最低-1。同主族从上到下:电子层数增多、原子半径增大;金属性增强、非金属性减弱(碱金属活泼性 Li<Na<K,卤素活泼性 F>Cl>Br);气态氢化物稳定性减弱(HF>HCl>HBr)。微粒半径比较规律:电子层数越多半径越大(同主族);电子层数相同时核电荷数越大半径越小(同周期);同种元素原子半径大于其阳离子、小于其阴离子;电子层结构相同的离子,核电荷数越大半径越小:$r(\\mathrm{O^{2-}})>r(\\mathrm{F^{-}})>r(\\mathrm{Na^{+}})>r(\\mathrm{Mg^{2+}})>r(\\mathrm{Al^{3+}})$。\\n**方法与思路**\\n金属性强弱判断依据:单质与水或酸置换氢的难易、最高价氧化物对应水化物碱性强弱、金属间的置换反应;非金属性强弱判断依据:与 H2 化合难易及气态氢化物稳定性、最高价氧化物对应水化物酸性强弱、非金属间的置换。比较半径三步:先看电子层数,层数相同看核电荷数,同种元素看得失电子。用具体反应佐证强弱,如 Cl2 能置换出 Br- 中的溴,说明非金属性 Cl>Br。\\n**常考题型与考法**\\n选择题与填空题:给定三种元素比较原子半径、金属性或非金属性、最高价氧化物对应水化物酸碱性、气态氢化物稳定性、主要化合价;由 Al(OH)3 的两性推断铝的金属性非金属性都不强;等电子离子半径排序;周期律与周期表结构、元素推断题联动(每年必考,多在推断题中比较元素性质)。\\n**易错提示**\\n原子半径最小的元素是 H;比较微粒半径必须明确比较对象是原子还是离子;气态氢化物稳定性顺序与氢化物水溶液酸性顺序不一致(稳定性 HF>HCl>HBr>HI,水溶液酸性反之),勿混淆;非金属性与单质活泼性通常一致,但表述要落到\"气态氢化物稳定性/最高价含氧酸酸性\"等证据上;O、F 一般不显正价;判断金属性不能只看原子失电子数多少,而看失电子能力(与酸碱反应剧烈程度)。",
