      "content": "**定义与核心概念**\\n\"位-构-性\"三角关系:原子结构(质子数、电子层、最外层电子数)决定元素在周期表中的位置与元素的性质;位置(周期、族)反映结构并预示性质;性质反推位置与结构。元素推断题即利用位置图、结构特征与性质信息反推元素,再完成比较与书写,是周期表与周期律知识的综合应用,常以选择题压轴或推断大题形式出现。\\n**核心公式/规律**\\n常用换算与对应:周期序数=电子层数;主族序数=最外层电子数;最高正价=主族序数(F、O 除外);最低负价=主族序数-8;原子序数=质子数=核电荷数。常见 10 电子微粒:Ne、Na+、Mg2+、Al3+、F-、O2-、H2O、NH3、CH4、HF。常见突破口:地壳中含量最多的元素是 O、其次 Si;含量最多的金属元素是 Al;短周期中金属性最强的是 Na;非金属性最强的是 F;最高价氧化物对应水化物呈两性的是 Al(OH)3(Al);与强酸、强碱都反应放出 H2 的单质是 Al;焰色呈黄色的是 Na,透过蓝色钴玻璃观察呈紫色的是 K;能使湿润红色石蕊试纸变蓝的气体是 NH3;形成化合物种类最多的是 C。\\n**方法与思路**\\n推断步骤:①圈限定(短周期、原子序数依次增大、同周期相邻等);②由周期表片段或结构数据(电子层、最外层电子数、得失电子形成 10 电子/18 电子离子)定位元素;③用周期律比较半径、金属性、氢化物稳定性、最高价氧化物对应水化物酸碱性,注意\"非金属性越强气态氢化物越稳定、最高价含氧酸酸性越强\";④按要求书写化学式、化学方程式与离子方程式,并把结果代回每个条件逐一验证。若条件给出离子(如 X 的离子与 Na+ 电子层结构相同),用等电子微粒反推核电荷数大小。\\n**常考题型与考法**\\n选择题:给出周期表片段与 3~5 条性质信息,判断元素符号、半径大小、金属性非金属性比较、气态氢化物稳定性、最高价氧化物对应水化物化学式及酸性强弱、10 电子微粒书写;大题则要求写推断依据、电子排布、方程式,并与氧化还原(价态变化)与元素化合物(钠、铝、铁、氯、硫、氮)知识接续。\\n**易错提示**\\n漏看\"短周期\"\"原子序数依次增大\"等限定致整体错位;把相对原子质量当原子序数;分不清\"气态氢化物稳定性\"与\"最高价氧化物对应水化物酸性\"两条非金属性判据;对 Al 的两性、F 无正价、O 无最高正价等特例不敏感;推断结果未回代验证(题给多条条件须全部满足)。",
