      "content": "**定义与核心概念**\\n物质的量(n)是表示含有一定数目粒子的集合体的物理量,单位摩尔(mol),是国际单位制七个基本物理量之一。它用于计量微观粒子(分子、原子、离子、质子、中子、电子及其特定组合),不能用于宏观物体,不能说\"1 mol 大米\"。使用物质的量必须指明粒子种类,如 1 mol O2 含 2 mol 氧原子、1 mol Na+ 等。1 mol 任何粒子的集合体所含粒子数与 0.012 kg 碳-12 中含有的碳原子数相同,约为 6.02×10^23,该数值称为阿伏伽德罗常数(NA,单位 mol-1),即 NA 约等于 6.02×10^23 mol-1;NA 的常见陷阱辨析由\"阿伏伽德罗常数\"专题承担,本节点掌握概念与换算。\\n**核心公式/规律**\\n核心换算链:$n=\\frac{N}{N_{A}}=\\frac{m}{M}$。摩尔质量(M):单位物质的量的物质所具有的质量,单位 g/mol;以 g/mol 为单位时,其数值等于该物质的相对分子(原子)质量,如 M(H2O)=18 g/mol、M(Fe)=56 g/mol,注意相对分子质量是无单位的比值。由化学式定组成微粒数:1 mol Na2CO3 含 2 mol Na+、1 mol CO32-;1 mol H2O 含 2 mol H 原子、1 mol O 原子,质子数与电子数各为 10 mol。\\n**方法与思路**\\n一切换算以\"求物质的量\"为枢纽:已知质量求粒子数时先 n=m/M 再 N=n·NA;反之先 n=N/NA 再求质量。求微粒总数必须结合化学式角标与物质构成方式(分子物质按分子计原子数,离子化合物按离子计)。常见求摩尔质量途径:由质量与物质的量之比求(M=m/n);由相对分子质量直接得;混合物的平均摩尔质量见气体摩尔体积节点。\\n**常考题型与考法**\\n基础计算题:9 g 水(0.5 mol)含分子数 0.5NA、电子数 5NA;64 g SO2 为 1 mol,含 2 mol 氧原子;由 3.2 g 某气体为 0.1 mol 求其摩尔质量为 32 g/mol(可能为 O2);同物质的量的 SO2 与 SO3 含氧原子数之比 2:3;化学式计算(某金属氯化物 MCl2 中氯的质量分数已知,求 M 的相对原子质量)。高考试卷中物质的量多与阿伏伽德罗常数专题结合命题。\\n**易错提示**\\nNA 有单位 mol-1,不能说\"阿伏伽德罗常数为 6.02×10^23\"(缺单位),6.02×10^23 只是近似值;\"1 mol 氧\"表述不明确,须指明氧原子还是氧分子;摩尔质量与相对分子质量数值相等但单位不同;n=m/M 中质量须用 g 并注意单位换算;粒子种类不指明时电子数、原子数最易算错。",
