      "content": "**定义与核心概念**\\n气体摩尔体积(Vm)是单位物质的量的气体所占的体积,单位 L/mol。气体体积主要由分子数目与分子间距离决定,而相同温度、压强下不同气体的分子间平均距离几乎相同,故同温同压下各种气体的摩尔体积相同,与气体种类无关。标准状况(STP,0 ℃、101 kPa)下,Vm 约为 22.4 L/mol。阿伏伽德罗定律:同温同压下,相同体积的任何气体都含有相同数目的分子,即物质的量相同。\\n**核心公式/规律**\\n$V=n\\cdot V_{m}$;标准状况下 $V=n\\times 22.4\\ \\mathrm{L/mol}$,即 $n=\\frac{V}{22.4\\ \\mathrm{L/mol}}$。阿伏伽德罗定律推论(同温同压):体积之比等于物质的量之比,$\\frac{V_{1}}{V_{2}}=\\frac{n_{1}}{n_{2}}$;密度之比等于摩尔质量之比,$\\frac{\\rho_{1}}{\\rho_{2}}=\\frac{M_{1}}{M_{2}}$。平均摩尔质量:$\\bar{M}=\\frac{m_{总}}{n_{总}}$,对混合气体也可用 $\\bar{M}=M_{1}x_{1}+M_{2}x_{2}$(x 为物质的量分数,同温同压即体积分数);标准状况下气体密度与摩尔质量关系:$M=22.4\\rho$(ρ 单位 g/L)。\\n**方法与思路**\\n气体换算链:n=m/M=V/Vm(仅标准状况可代 22.4);混合气平均摩尔质量三种求法(定义式、标况密度法、体积分数加权法);相对密度法:某气体对 H2 的相对密度为 d 时 M=2d。比较同温同压下两气体体积即比较物质的量;等质量两气体体积之比等于摩尔质量的反比(如等质量 H2 与 O2 体积比 16:1)。\\n**常考题型与考法**\\n计算题:标准状况下 2.24 L CO2 的物质的量为 0.1 mol、质量为 4.4 g;标况密度 1.25 g/L 的气体摩尔质量为 28 g/mol(可猜 N2 或 CO);混合气体组成计算(标况 11.2 L CO 与 CO2 混合气共 18 g,列 n 与 m 方程组求解);气体体积在 NO2 溶于水等反应中的变化计算见氮及其化合物节点。\\n**易错提示**\\n22.4 L/mol 只适用于标准状况下的气体:标准状况下 H2O、乙醇、SO3、CCl4、苯等为液体或固体,不能套用;非标准状况(如常温常压)下 22.4 L 气体不是 1 mol;气体摩尔体积对纯气体与混合气体同样适用;温度、压强影响气体体积但几乎不影响固体与液体体积(粒子间距不同);计算时单位要统一(L、mol、g/mol)。",
