      "content": "**定义与核心概念**\\n物质的量浓度(cB)表示单位体积溶液中所含溶质 B 的物质的量,cB=nB/V,单位 mol/L;其中 V 是溶液体积,不是溶剂体积。它与质量分数(w)都是表示溶液组成的方法。配制一定物质的量浓度的溶液需用容量瓶(细颈梨形瓶,标注使用温度、容积与刻度线,常见规格 100、250、500、1000 mL):只能用于配制规定容积的溶液,不能加热,不能久存试剂,不能用于溶解或稀释,用前须检查是否漏水;需要 480 mL 溶液时应选 500 mL 容量瓶并按 500 mL 计算。\\n**核心公式/规律**\\n$c=\\frac{n}{V}$,变形 $n=cV$。稀释(或混合)前后溶质的物质的量不变:$c_{1}V_{1}=c_{2}V_{2}$。物质的量浓度与质量分数换算:$c=\\frac{1000\\rho w}{M}$(ρ 单位为 g/cm3)。完全电离的电解质中离子浓度等于电解质浓度乘角标:0.5 mol/L Na2SO4 溶液中 c(Na+)=1 mol/L、c(SO42-)=0.5 mol/L。配制步骤(固体溶质):计算 m=cVM→称量→在烧杯中溶解并冷却至室温→玻璃棒引流转移入容量瓶→洗涤烧杯与玻璃棒 2~3 次、洗涤液一并转移→定容(先加水至刻度线 1~2 cm 处,改胶头滴管滴加至凹液面最低点与刻度线相切)→摇匀→装瓶贴签。\\n**方法与思路**\\n误差分析统一由 c=n/V 推理:使 n 偏小的操作使 c 偏低(药品潮解或含杂质、称量时砝码药品放反且用了游码、未洗涤烧杯玻璃棒、转移时洒落);使 V 偏大的操作使 c 偏低(定容时仰视读数、加水超过刻度线只能重配);定容俯视使 V 偏小、c 偏高;未冷却至室温就转移定容,冷却后液面下降,c 偏高;摇匀后发现液面低于刻度线属正常现象,不能再加水;容量瓶中原有少量蒸馏水不影响结果(定容会补足)。稀释配制时,量筒仰视量取浓溶液使溶质偏多、c 偏高,俯视则偏低。\\n**常考题型与考法**\\n计算:直接求 c;稀释求所需浓液体积(配制 500 mL 0.2 mol/L 盐酸需 18.4 mol/L 浓盐酸约 5.4 mL);由密度与质量分数求 c(98% 浓硫酸、密度 1.84 g/cm3,其浓度约为 18.4 mol/L);由取出溶液体积判断浓度不变而物质的量按比例减小。实验题:配制操作正误与排序、仪器选择、误差分析判断\"偏高/偏低/无影响\"。\\n**易错提示**\\n溶液体积不等于水的体积(1 mol NaCl 溶于 1 L 水所得浓度不是 1 mol/L);两种溶液混合体积不能简单相加;量筒只能粗量且不能加热、不能作反应容器,不能用于配制溶液;定容俯视/仰视的判断与量筒读数相反(量筒俯视读数偏大),务必分清仪器;定容后摇匀液面下降不能再加水;称量 NaOH 等易潮解药品应放在小烧杯中快速称量;容量瓶规格固定,无 480 mL 规格。",
