      "keywords": [
        "离子反应",
        "离子方程式",
        "拆写规则",
        "电荷守恒",
        "少量过量",
        "发生条件"
      ],
      "content": "**定义与核心概念**\\n在溶液中(或在熔融状态)有离子参加或生成的化学反应称为离子反应,常见于电解质溶液之间。用实际参加反应的离子符号表示化学反应的式子叫离子方程式,它能表示同一类型的反应,揭示反应实质。离子反应发生条件:复分解型离子反应需生成沉淀、气体或难电离物质(水、弱酸、弱碱),本质是溶液中某些离子浓度减小;氧化还原型离子反应条件见氧化还原节点。\\n**核心公式/规律**\\n书写步骤\"写、拆、删、查\":先写正确的化学方程式,再把易溶于水且完全电离的物质拆成离子,删去两边未参加反应的离子,最后检查质量守恒与电荷守恒。写化学式不拆的:单质、氧化物、气体、难溶物、弱电解质(弱酸、弱碱、水)、非电解质,以及多元弱酸的酸式酸根(HCO3-、HS- 等整体保留);微溶物作反应物时澄清溶液拆、悬浊液(石灰乳)不拆。典型基础离子方程式:$\\mathrm{CO_{3}^{2-}+2H^{+}=H_{2}O+CO_{2}\\uparrow}$、$\\mathrm{HCO_{3}^{-}+H^{+}=H_{2}O+CO_{2}\\uparrow}$、$\\mathrm{H^{+}+OH^{-}=H_{2}O}$(强酸与强碱且生成可溶性盐时适用)、$\\mathrm{Fe+2H^{+}=Fe^{2+}+H_{2}\\uparrow}$、$\\mathrm{2Fe^{3+}+Cu=2Fe^{2+}+Cu^{2+}}$。少量过量与滴加顺序改变产物:CO2 少量通入 NaOH 溶液生成 CO32-,过量生成 HCO3-;详见钠、铝节点中的实例。\\n**方法与思路**\\n离子方程式正误判断\"四查\":①查客观事实(Fe 与稀盐酸生成 Fe2+ 而非 Fe3+,Cu 与稀盐酸不反应,硝酸与金属不放 H2);②查拆分是否正确(CH3COOH、NH3·H2O、H2O、CaCO3 不拆;HCl、NaOH、NaCl 拆);③查守恒(质量守恒与电荷守恒,如 Fe+2H+ 生成 Fe3+ 的式子电荷不平);④查配比与少量过量(铝盐与 NaOH 少量生成 Al(OH)3、过量生成 AlO2-)。解题先定位反应类型(复分解型还是氧化还原型),再按上述顺序核查。\\n**常考题型与考法**\\n离子方程式正误判断是高考每年必考题型,四个选项逐一\"四查\"排除;书写题根据实验现象或转化关系书写,如 Na2O2 与水、Cl2 与 NaOH 溶液、铝与 NaOH 溶液、铁盐与铜等(见相应元素节点);少量过量书写与离子共存题联合命题。\\n**易错提示**\\nHCO3- 不能拆成 H+ 与 CO32-;HSO4- 在水中可拆成 H+ 与 SO42-(强酸酸式盐),书写时区分;漏写参加反应的离子(如 Ba(OH)2 与 H2SO4 反应应写 $\\mathrm{Ba^{2+}+2OH^{-}+2H^{+}+SO_{4}^{2-}=BaSO_{4}\\downarrow+2H_{2}O}$);浓硫酸与金属的反应不写离子方程式;生成微溶物且作生成物时写化学式并标沉淀;忽略电荷守恒是最高频错误。",
