      "content": "**定义与核心概念**\\n凡有元素化合价升降的化学反应是氧化还原反应,判断依据是反应前后元素化合价发生变化;其本质是电子的转移(包括电子的得失与共用电子对的偏移)。概念关系:失电子(化合价升高)的物质被氧化,作还原剂,发生氧化反应,生成氧化产物;得电子(化合价降低)的物质被还原,作氧化剂,发生还原反应,生成还原产物。记忆口诀:\"升失氧、降得还\"。氧化与还原同时发生、同时存在,氧化剂与还原剂可以不是同一种物质,也可以在同一物质内部发生(歧化与分解反应,如 Na2O2 与水反应、KClO3 分解)。\\n**核心公式/规律**\\n常见氧化剂:Cl2、O2、浓硫酸、硝酸、酸性 KMnO4 溶液、Fe3+、H2O2、Na2O2 等;常见还原剂:活泼金属、H2、C、CO、Fe2+、I-、S2-、SO2(SO32-)等。元素价态与性质:最高价态只有氧化性(如浓硫酸中 S 为+6、KMnO4 中 Mn 为+7),最低价态只有还原性(如 Cl-、S2-),中间价态既有氧化性又有还原性(SO2 中 S 为+4、Fe2+、H2O2 中 O 为-1)。注意特例化合价:Na2O2 与 H2O2 中氧为-1,Fe3O4 中铁为+2 与+3。电子转移表示:双线桥从反应物中变价元素指向生成物中同种元素,标注\"得 ne-/失 ne-\",得电子总数等于失电子总数;单线桥由还原剂中失电子元素指向氧化剂中得电子元素,只标转移电子总数 ne-。电子守恒:氧化剂得电子总数=还原剂失电子总数。\\n**方法与思路**\\n判断与计算的步骤:①标出发生变化的元素化合价(会用常见价态与 Na2O2、Fe3O4 等特例);②确认有升降即氧化还原反应;③确定氧化剂、还原剂及各自产物;④算电子转移数:先看一个粒子得失电子数,再乘以该粒子的物质的量。例:2Na2O2+2CO2=2Na2CO3+O2 中,每 2 mol Na2O2 转移 2 mol 电子;3Cu+8HNO3(稀)=3Cu(NO3)2+2NO↑+4H2O 中,3 mol Cu 共转移 6 mol 电子。\\n**常考题型与考法**\\n概念辨析选择题:判断某反应是否氧化还原(有单质参加或生成不一定就是,如 3O2 生成 2O3 化合价未变;CaCO3 高温分解不是;CaO+H2O 化合不是);四大基本反应类型与氧化还原的交叉关系(置换必是、复分解必不是、化合分解不一定);指出氧化剂、还原剂、被氧化与被还原的元素;转移电子数计算与双线桥、单线桥正误判断(箭头指向、得失标注);\"还原产物\"与\"氧化产物\"归属。\\n**易错提示**\\nFe 与 Cl2 点燃生成 FeCl3(强氧化剂),Fe 与盐酸生成 Fe2+;电子转移数要按实际变价原子数计算,不能按方程式系数简单乘化合价差(2Na2O2 与 2CO2 反应共转移 2 mol 电子);氧化剂被还原生成还原产物,氧化产物是还原剂被氧化所得,两者勿张冠李戴;只标出化合价但实际未变(如同素异形体转化)不算氧化还原;得失电子守恒是计算一切氧化还原问题的总钥匙。",
