      "content": "**定义与核心概念**\\n本节点整合氧化还原的规律与技能:①强弱律:同一反应中氧化剂的氧化性强于氧化产物,还原剂的还原性强于还原产物,据此可由已知反应比较物质氧化性、还原性强弱,也可判断陌生反应能否发生;②先后律:同一氧化剂与多种还原剂相遇,还原性强者先被氧化(同一还原剂遇多种氧化剂同理),用于判断反应顺序与最终产物;③守恒律:得失电子守恒,是配平方程式与定量计算的依据;④价态律:同种元素高价与低价间反应\"只靠拢、不交叉\"(归中),中间价态歧化生成高、低价。\\n**核心公式/规律**\\n重要强弱序列(应熟记):氧化性 Cl2>Br2>Fe3+>I2,对应还原性 Cl-<Br-<Fe2+<I-。应用:Fe3+ 能氧化 I- 生成 I2($\\mathrm{2Fe^{3+}+2I^{-}=2Fe^{2+}+I_{2}}$)却不能氧化 Br-;向 FeBr2 溶液通 Cl2 先氧化 Fe2+ 后氧化 Br-;向含 I-、Fe2+ 的溶液通 Cl2 先生成 I2。歧化:同一物质中同种元素由同一价态部分升高、部分降低,如 $\\mathrm{Cl_{2}+2NaOH=NaCl+NaClO+H_{2}O}$、$\\mathrm{2Na_{2}O_{2}+2H_{2}O=4NaOH+O_{2}\\uparrow}$;归中:不同价态的同种元素向中间价态靠拢,如 $\\mathrm{SO_{2}+2H_{2}S=3S\\downarrow+2H_{2}O}$、$\\mathrm{KClO_{3}+6HCl(浓)=KCl+3Cl_{2}\\uparrow+3H_{2}O}$(KClO3 中+5 价的氯降至 0,部分-1 价氯升至 0,不交叉降到-1 或升到+5)。\\n**方法与思路**\\n配平步骤(化合价升降法):①标出变价元素的化合价;②求化合价升降数的最小公倍数,确定氧化剂与还原剂(或其产物的计量数);③用观察法配平其他物质(原子守恒);④若是离子方程式再检查电荷守恒(介质为酸性补 H+、碱性补 OH-,用 H2O 平衡氧氢)。配平后再用电子守恒求转移电子总数、推算未知产物价态或比较反应物计量比。例:3Cu+8HNO3(稀)=3Cu(NO3)2+2NO↑+4H2O 中 8 mol 硝酸只有 2 mol 被还原为 NO,共转移 6 mol 电子,硝酸同时表现酸性与氧化性。\\n**常考题型与考法**\\n强弱排序题:给出 2~3 个氧化还原方程式排出氧化性或还原性顺序,再判断给定反应能否发生;\"通入氧化剂\"顺序与产物图像题(FeI2、FeBr2 溶液与 Cl2 的物质的量关系);陌生氧化还原方程式的配平与电子转移计算(填空:配平系数、转移电子数、某元素被氧化或被还原的物质的量);歧化与归中辨析。\\n**易错提示**\\n氧化性强弱比的是\"得电子能力\"而非\"得电子数目\":浓硝酸还原产物 NO2 只得 1 个电子,氧化性却强于得 3 个电子的稀硝酸(产物 NO);价态高低不等于强弱(HCl 中-1 价氯无氧化性,Cl2 中 0 价却有强氧化性);比较强弱要与氧化产物比较而非与还原剂比较;配平必须先定电子守恒再配其他原子,离子方程式勿忘电荷守恒;歧化是\"同价变两价\",归中是\"两价向中靠\",方向勿混。",
