      "content": "**定义与核心概念**\\n钠是碱金属代表,原子最外层 1 个电子,化学性质极活泼,自然界只以化合态存在(如 NaCl)。单质钠银白色、质软(可用小刀切割)、密度小于水、熔点较低,保存在煤油中以隔绝空气和水。切开断面银白色,在空气中迅速变暗(表面生成 Na2O)。钠的化合物:Na2O 为白色碱性氧化物;Na2O2 为淡黄色固体,氧元素为-1 价;Na2CO3 俗称纯碱(苏打)、NaHCO3 俗称小苏打,二者均属盐类。焰色试验是元素的物理性质:钠的焰色呈黄色,观察钾的浅紫色焰色须透过蓝色钴玻璃滤去钠的黄光。\\n**核心公式/规律**\\n钠与水:$\\mathrm{2Na+2H_{2}O=2NaOH+H_{2}\\uparrow}$(离子方程式 $\\mathrm{2Na+2H_{2}O=2Na^{+}+2OH^{-}+H_{2}\\uparrow}$),现象\"浮、熔、游、响\",滴入酚酞溶液变红。钠与氧气:常温 $\\mathrm{4Na+O_{2}=2Na_{2}O}$;点燃时黄色火焰,$\\mathrm{2Na+O_{2}=Na_{2}O_{2}}$。过氧化钠与水、二氧化碳:$\\mathrm{2Na_{2}O_{2}+2H_{2}O=4NaOH+O_{2}\\uparrow}$、$\\mathrm{2Na_{2}O_{2}+2CO_{2}=2Na_{2}CO_{3}+O_{2}}$,两反应中每 2 mol Na2O2 均转移 2 mol 电子,Na2O2 既作氧化剂又作还原剂。碳酸氢钠受热分解:$\\mathrm{2NaHCO_{3}=Na_{2}CO_{3}+H_{2}O+CO_{2}\\uparrow}$(加热);相互转化:Na2CO3+CO2+H2O=2NaHCO3,NaHCO3+NaOH=Na2CO3+H2O。\\n**方法与思路**\\n①钠投入盐溶液先与水反应,不能置换出盐中的金属:投入 CuSO4 溶液生成 H2 与 Cu(OH)2 蓝色沉淀。②Na2O2 增重规律:与 CO2 反应固体增重等于等物质的量 CO 的质量(每 2 mol CO2 参与增重 56 g),故可作呼吸面具、潜水艇的供氧剂。③鉴别 Na2CO3 与 NaHCO3:固体用加热法(放出使澄清石灰水变浑浊气体的是 NaHCO3);溶液加 CaCl2(Na2CO3 生成白色 CaCO3 沉淀,NaHCO3 无明显现象),不能用澄清石灰水(两者均产生沉淀)。除杂:Na2CO3 固体中 NaHCO3 用加热;NaHCO3 溶液中 Na2CO3 通入 CO2。④滴加顺序:盐酸逐滴加入 Na2CO3 溶液,先无气泡(CO32-+H+=HCO3-)后产生气泡(HCO3-+H+=H2O+CO2↑);Na2CO3 溶液滴入过量盐酸则立即放气。⑤侯氏制碱(联合制碱):饱和食盐水先吸氨后通 CO2,NaCl+NH3+CO2+H2O=NaHCO3↓+NH4Cl,过滤后加热 NaHCO3 得 Na2CO3。\\n**常考题型与考法**\\n钠与水反应现象及解释;Na2O2 与 CO2、H2O 的增重、差量与转移电子数计算;向 Na2CO3 溶液滴加盐酸的 CO2 体积图像;Na2CO3/NaHCO3 与盐酸反应快慢比较、鉴别与除杂方案评价;侯氏制碱流程;焰色试验的操作与观察。\\n**易错提示**\\nNa2O2 中氧为-1 价、固体淡黄色,Na2O 为白色;钠不能从盐溶液中置换出金属(先与水反应);Na2CO3 俗名纯碱却是盐(溶液呈碱性与 CO32- 水解有关);NaHCO3 既能与酸又能与 NaOH 反应;鉴别两者选 CaCl2 或 BaCl2 而不选石灰水;Na2O2 与 H2O、CO2 的反应中每 mol Na2O2 转移 1 mol 电子;观察钾的焰色必须透过蓝色钴玻璃。",
