      "note": "钠族化合物是元素化合物第一课:Na2O2 的歧化、碳酸盐的离子方程式与滴加顺序、侯氏制碱流程都向上调用离子/氧化还原工具并挂接流程节点,imp/core 4;与氯节点经\"电解饱和食盐水\"共用氯化钠主线。",
