      "content": "**定义与核心概念**\\n铝是地壳中含量最多的金属元素,质轻、导电导热性好,广泛用于合金。铝表面易生成致密的 Al2O3 薄膜,常温下遇浓硫酸、浓硝酸钝化,故铝制品耐腐蚀。Al2O3 是白色、熔点很高的两性氧化物(刚玉的主要成分);Al(OH)3 是白色胶状的两性氢氧化物。Al3+、Al(OH)3、AlO2-(偏铝酸根)之间的相互转化称\"铝三角\",两性是铝及其化合物最核心的性质。\\n**核心公式/规律**\\n单质铝:与酸 $\\mathrm{2Al+6HCl=2AlCl_{3}+3H_{2}\\uparrow}$(离子式 $\\mathrm{2Al+6H^{+}=2Al^{3+}+3H_{2}\\uparrow}$);与强碱 $\\mathrm{2Al+2NaOH+2H_{2}O=2NaAlO_{2}+3H_{2}\\uparrow}$(离子式 $\\mathrm{2Al+2OH^{-}+2H_{2}O=2AlO_{2}^{-}+3H_{2}\\uparrow}$,注意水参加反应)。氧化铝:$\\mathrm{Al_{2}O_{3}+6H^{+}=2Al^{3+}+3H_{2}O}$、$\\mathrm{Al_{2}O_{3}+2OH^{-}=2AlO_{2}^{-}+H_{2}O}$。氢氧化铝:$\\mathrm{Al(OH)_{3}+3H^{+}=Al^{3+}+3H_{2}O}$、$\\mathrm{Al(OH)_{3}+OH^{-}=AlO_{2}^{-}+2H_{2}O}$;受热分解 2Al(OH)3=Al2O3+3H2O(加热)。制备 Al(OH)3 用弱碱弱酸路线:铝盐加氨水 $\\mathrm{Al^{3+}+3NH_{3}\\cdot H_{2}O=Al(OH)_{3}\\downarrow+3NH_{4}^{+}}$;偏铝酸盐溶液通 CO2 $\\mathrm{AlO_{2}^{-}+CO_{2}+2H_{2}O=Al(OH)_{3}\\downarrow+HCO_{3}^{-}}$。铝热反应(冶炼难熔金属、焊接钢轨):2Al+Fe2O3=Al2O3+2Fe(高温,铝是强还原剂)。\\n**方法与思路**\\n滴加顺序与图像:向 AlCl3 溶液逐滴加 NaOH,先出现 Al(OH)3 沉淀后溶解,消耗 NaOH 物质的量比 n(Al3+):n(OH-)=1:3 时沉淀最多,1:4 时恰好完全溶解;反向滴加(AlCl3 滴入过量 NaOH)先无沉淀后有沉淀。Al(OH)3 溶于强碱不溶于弱碱(氨水),故制取用氨水;Al(OH)3 溶于强酸不溶于弱酸(碳酸),故向 NaAlO2 通 CO2 沉淀不溶。双水解:Al3+ 与 AlO2-、HCO3-、CO32-、S2- 不能共存,泡沫灭火器原理 Al3+ 与 HCO3- 反应生成 Al(OH)3 与 CO2。明矾 KAl(SO4)2·12H2O 净水:Al3+ 水解生成的 Al(OH)3 胶体吸附悬浮杂质,只能净水不能消毒。\\n**常考题型与考法**\\n两性反应离子方程式书写与正误判断;沉淀量随试剂用量变化的图像题(确定铝盐与 NaOH 用量比、溶液中离子种类);Al(OH)3 制备试剂的选择(氨水、CO2);铝三角转化与离子共存、流程除杂结合(铝土矿提铝:碱浸得 NaAlO2,通 CO2 得 Al(OH)3,煅烧得 Al2O3,电解熔融氧化铝冶炼);等质量铝与足量酸、足量碱反应放 H2 相等;铝热反应的应用。\\n**易错提示**\\n铝与 NaOH 反应的离子方程式必须写水参与(2Al+2OH-+2H2O);Al(OH)3 不溶于过量氨水,也不溶于碳酸(通 CO2 过量沉淀不消失);Al3+ 与 OH- 按 1:3、1:4 两段计量是图像题命门;Al2O3、Al(OH)3 与强碱反应生成 AlO2-;铝盐与过量 NaOH 得不到沉淀;AlCl3 与 NaOH 互滴现象不同;常温铝遇浓硫酸、浓硝酸钝化,不是不反应。",
