      "content": "**定义与核心概念**\\n铁是典型的变价金属,常见价态+2、+3:遇弱氧化剂(盐酸、稀硫酸、Cu2+、硫)生成+2 价,遇强氧化剂(Cl2、足量稀硝酸)生成+3 价。铁的氧化物:FeO 黑色、Fe2O3 红棕色(俗称铁红,红色颜料)、Fe3O4 黑色磁性(可看作 FeO·Fe2O3,铁呈+2、+3 两种价态);氢氧化物:Fe(OH)2 白色、Fe(OH)3 红褐色,均难溶于水。自然界:磁铁矿 Fe3O4、赤铁矿 Fe2O3 等;高炉炼铁:Fe2O3+3CO=2Fe+3CO2(高温)。铜(轻量了解):紫红色金属,CuO 黑色,Cu(OH)2 蓝色,胆矾 CuSO4·5H2O 蓝色,Cu2+ 溶液蓝色;铜在金属活动性顺序中位于氢后,不与稀盐酸、稀硫酸反应。\\n**核心公式/规律**\\n铁三角转化是本节点主线:Fe→Fe2+:Fe+2H+=Fe2++H2↑、Fe+Cu2+=Fe2++Cu;Fe→Fe3+:2Fe+3Cl2=2FeCl3(点燃);Fe2+→Fe3+:2Fe2++Cl2=2Fe3++2Cl-、2Fe2++H2O2+2H+=2Fe3++2H2O,Fe2+ 溶液久置被空气氧化变黄;Fe3+→Fe2+:2Fe3++Fe=3Fe2+、2Fe3++Cu=2Fe2++Cu2+(FeCl3 溶液腐蚀铜制印刷线路板)。Fe(OH)2 在空气中被氧化:4Fe(OH)2+O2+2H2O=4Fe(OH)3(白色迅速变灰绿色,最终红褐色)。铁与水蒸气:3Fe+4H2O(g)=Fe3O4+4H2(高温)。铜的转化:CuO+H2SO4=CuSO4+H2O;Fe+CuSO4=FeSO4+Cu(湿法炼铜);Cu(OH)2 受热分解为 CuO;无水 CuSO4 白色粉末遇水变蓝,可检验水的存在。\\n**方法与思路**\\n检验:Fe3+ 用 KSCN 溶液,变血红色(Fe3++3SCN- ⇌ Fe(SCN)3);或加 NaOH 生成红褐色沉淀。Fe2+ 检验须排除 Fe3+ 干扰:先加 KSCN 无现象,再滴氯水(或 H2O2)变红说明原溶液含 Fe2+;也可加 NaOH 观察白色→灰绿→红褐色的颜色变化。保存亚铁盐溶液常加少量铁粉(2Fe3++Fe=3Fe2+),防止 Fe2+ 被氧化;制备 Fe(OH)2 要防氧化,胶头滴管应伸入液面下滴加碱液。价态判断看氧化剂强弱:Cl2、浓硝酸等强氧化剂把铁氧化到+3,盐酸、稀硫酸、Cu2+、S 只能到+2。\\n**常考题型与考法**\\n铁三角转化的试剂选择(实现 Fe2+→Fe3+ 加 Cl2、H2O2;Fe3+→Fe2+ 加 Fe、Cu);Fe2+/Fe3+ 检验方案设计与干扰排除;印刷线路板腐蚀的离子方程式与电子转移计算;铁与稀硝酸的定量(硝酸足量生成 Fe3+,铁过量生成 Fe2+);流程中\"氧化 Fe2+ 后调 pH 沉淀除杂\";铜及其化合物常以 CuO、Cu(OH)2、胆矾的颜色与转化出选择或填空。\\n**易错提示**\\nFe 与 Cl2、足量稀硝酸生成 Fe3+,与盐酸、稀硫酸、硫、Cu2+ 反应生成 Fe2+;Fe3+ 与 I-、S2- 发生氧化还原不能共存(Fe3+ 氧化 I- 生成 I2,不存在 FeI3);检验 Fe2+ 必须先加 KSCN 排除 Fe3+ 干扰;Fe(OH)2 变色\"白→灰绿→红褐\"是检验 Fe2+ 的经典现象;Fe3O4 中两种价态并存,书写其与酸反应生成 Fe2+ 与 Fe3+;Cu 与浓硫酸、硝酸的反应见硫、氮节点,Cu 不能与稀盐酸反应。",
