      "content": "**定义与核心概念**\\n氯是卤素代表元素,原子最外层 7 个电子,易得 1 个电子,Cl2 是活泼的强氧化性非金属单质。Cl2 为黄绿色、有刺激性气味的有毒气体,密度比空气大,能溶于水(1 体积水约溶解 2 体积 Cl2),易液化;实验室使用要在通风橱或通风处进行,多余氯气用 NaOH 溶液吸收。氯水是 Cl2 溶于水得到的混合物,含\"三分子三离子\":分子为 Cl2、H2O、HClO,离子为 H+、Cl-、ClO-(及少量 OH-)。次氯酸 HClO 是弱酸、不稳定、有强氧化性,能杀菌消毒和漂白。\\n**核心公式/规律**\\n氯与水(可逆):$\\mathrm{Cl_{2}+H_{2}O\\rightleftharpoons HCl+HClO}$;次氯酸见光分解:2HClO=2HCl+O2↑(光照),故久置氯水逐渐变为稀盐酸,失去漂白性,氯水须现用现配。漂白的是 HClO,干燥氯气没有漂白性。氯与金属、非金属:2Fe+3Cl2=2FeCl3(点燃,铁生成+3 价)、Cu+Cl2=CuCl2(点燃,棕黄色烟,溶于水呈蓝绿色);H2 在 Cl2 中点燃安静燃烧,苍白色火焰、瓶口有白雾,生成 HCl。氯与碱(歧化):$\\mathrm{Cl_{2}+2NaOH=NaCl+NaClO+H_{2}O}$(吸收尾气;工业制 84 消毒液,有效成分 NaClO);$\\mathrm{2Cl_{2}+2Ca(OH)_{2}=CaCl_{2}+Ca(ClO)_{2}+2H_{2}O}$(制漂白粉,主要成分是 CaCl2 与 Ca(ClO)2,有效成分 Ca(ClO)2);漂白粉在空气中:Ca(ClO)2+CO2+H2O=CaCO3↓+2HClO(强酸制弱酸,故漂白粉须密封保存);84 消毒液与洁厕灵(含盐酸)混用放出 Cl2:NaClO+2HCl=NaCl+Cl2↑+H2O,严禁混用。\\n**方法与思路**\\n实验室制氯气:MnO2+4HCl(浓)=MnCl2+Cl2↑+2H2O(加热;稀盐酸不反应,随反应进行盐酸变稀反应停止)。净化:饱和食盐水除去 HCl,浓硫酸干燥;收集:向上排空气法或排饱和食盐水法(Cl2 能溶于水,饱和食盐水中溶解度很小);尾气用 NaOH 溶液吸收;检验:湿润的淀粉碘化钾试纸变蓝(Cl2 氧化 I- 生成 I2)或观察黄绿色。工业上电解饱和食盐水(氯碱工业):2NaCl+2H2O=2NaOH+H2↑+Cl2↑(电解)。Cl- 的检验:先加稀硝酸酸化(排除 CO32- 干扰),再滴加 AgNO3 溶液,生成不溶于稀硝酸的白色沉淀:Ag++Cl-=AgCl↓。氯及其化合物按价态串线掌握:Cl-(-1)、Cl2(0)、ClO-(+1):Cl2 与水、碱歧化;强氧化剂(MnO2、KMnO4)氧化 Cl- 制 Cl2;次氯酸盐遇酸生成 HClO 或 Cl2。\\n**常考题型与考法**\\n氯水成分与性质的综合考查:加石蕊先变红后褪色(H+ 酸性、HClO 漂白)、加 AgNO3 出现白色沉淀(Cl-)、加 NaHCO3 放出 CO2(H+)、加品红褪色(HClO)、加淀粉碘化钾试纸变蓝(Cl2);干燥氯气与潮湿氯气漂白性对比;实验室制氯装置图正误(净化顺序、收集方法、尾气处理);漂白粉的制备、成分、失效与保存;Cl- 检验方案评价;氯气泄漏处理(向高处转移,用浸有碱性溶液(如 NaHCO3 或肥皂水)的毛巾捂住口鼻)。\\n**易错提示**\\n干燥 Cl2 无漂白性;HClO 是弱酸,离子方程式中写化学式不拆;铁与 Cl2 直接生成 FeCl3;MnO2 必须与浓盐酸共热;Cl2 不能排水法收集,可用向上排空气法或排饱和食盐水法;漂白粉有效成分是 Ca(ClO)2 而非 CaCl2;久置氯水失去漂白性并显酸性;HClO 光照分解生成 HCl 与 O2(不是 Cl2)。",
