      "note": "氯及其化合物集\"氯水成分分析、歧化、实验室制备、漂白检验\"于一身,是卤素与氧化还原应用的样板节点,imp/core 4;与钠(电解食盐水)、铁(氯化铁)、离子方程式及强弱规律(Cl2 氧化性序列)互链紧密。",
