      "content": "**定义与核心概念**\\n硫位于第三周期ⅥA 族。单质硫(硫黄)是黄色固体,难溶于水、微溶于酒精、易溶于二硫化碳;与变价金属反应生成低价硫化物,如 Fe+S=FeS(加热)。SO2 是无色、有刺激性气味的有毒气体,密度比空气大,易溶于水(约 1 体积水溶解 40 体积 SO2),是硫酸型酸雨的主要成因气体。SO2 中硫为+4 价(中间价态),以还原性为主,兼有氧化性与漂白性。浓硫酸具有吸水性、脱水性与强氧化性三大特性;稀硫酸是强酸,但不表现强氧化性(其氧化性来自 H+)。\\n**核心公式/规律**\\nSO2 与水:$\\mathrm{SO_{2}+H_{2}O\\rightleftharpoons H_{2}SO_{3}}$(亚硫酸是弱酸);酸性氧化物通性:SO2+2NaOH=Na2SO3+H2O(尾气可用碱液吸收),SO2 使澄清石灰水变浑浊、过量又变清(与 CO2 相似)。还原性:$\\mathrm{SO_{2}+Cl_{2}+2H_{2}O=H_{2}SO_{4}+2HCl}$(等物质的量混合时漂白性相互抵消)、能使溴水与酸性高锰酸钾溶液褪色(还原性褪色,不是漂白)、催化氧化 2SO2+O2⇌2SO3(催化剂、加热)。氧化性:SO2+2H2S=3S↓+2H2O。漂白性:SO2 与品红等有色物质化合生成不稳定无色物质,品红褪色后加热复红(暂时性漂白);氯水(HClO)、Na2O2、H2O2 的漂白是氧化漂白,不可逆;SO2 通入石蕊溶液只变红不褪色。浓硫酸:吸水性与脱水性的区别(吸收游离水可作干燥剂,可干燥 Cl2、SO2、CO2、O2、H2、CO 等,不能干燥 NH3 及还原性气体 H2S、HBr、HI;脱水性如蔗糖炭化:把蔗糖中氢氧按水的组成脱去,生成碳并膨胀);强氧化性(加热):Cu+2H2SO4(浓)=CuSO4+SO2↑+2H2O、C+2H2SO4(浓)=CO2↑+2SO2↑+2H2O(加热),常温使 Fe、Al 钝化(可用铁罐车运输浓硫酸);稀释时\"酸入水、沿器壁、不断搅拌\"。\\n**方法与思路**\\nSO2 的检验与鉴别:通入品红溶液褪色、加热恢复红色(Cl2 使品红褪色后加热不复红);与 CO2 鉴别用品红或溴水、酸性高锰酸钾(CO2 均不褪色)。SO42- 的检验:先加足量稀盐酸酸化(排除 CO32-、SO32-、Ag+ 干扰;不能用硝酸,硝酸会把 SO32- 氧化成 SO42-),再滴 BaCl2 溶液,生成不溶于盐酸的白色沉淀:Ba2++SO42-=BaSO4↓。酸雨 pH<5.6;防治:燃煤脱硫(钙基固硫)、工业尾气碱液吸收、开发清洁能源。工业制硫酸(接触法):煅烧硫铁矿制 SO2,催化氧化为 SO3,再用水(浓硫酸)吸收,流程见工艺流程节点。\\n**常考题型与考法**\\nSO2 漂白与还原性辨析(品红、溴水、酸性高锰酸钾、石蕊四种试剂的现象差别);SO2 与 Cl2 等物质的量混合通入品红不褪色;浓硫酸三性判断(蓝矾变白体现吸水性、蔗糖变黑体现脱水性、与 Cu 共热放出 SO2 体现强氧化性);铜与浓硫酸实验的装置与检验顺序(品红检验 SO2);SO42- 检验方案评价;酸雨与脱硫的环保题。\\n**易错提示**\\nSO2 使溴水、酸性高锰酸钾褪色是还原性而非漂白性;SO2 漂白不稳定(加热复红),HClO 漂白不可逆;浓硫酸不能干燥 NH3(碱性)与 H2S、HBr、HI(还原性);铜与浓硫酸反应须加热,反应中硫酸变稀后反应停止(稀硫酸不与铜反应);检验 SO42- 酸化不能用硝酸;SO2 易溶于水,不用排水法收集;亚硫酸是弱酸,其盐 Na2SO3 中硫为+4 价有还原性。",
