      "note": "硅按\"轻量了解级\"处理,imp 3/core 2:考点为材料对应与两个特殊反应,主要价值是酸性氧化物分类的个性案例与高纯硅流程素材;与氧化物、酸碱盐通性及流程节点三点链接即可,不必向元素主干延伸。",
