      "content": "**定义与核心概念**：泡利原理:同一原子轨道内最多只能容纳2个电子,且这2个电子的自旋方向必须相反(同一原子中不存在运动状态完全相同的电子),图中用↑↓表示自旋相反的一对电子。洪特规则:基态原子填充同一能级的等价轨道(如三个2p轨道)时,电子优先分占不同轨道,且分占时自旋方向相同。轨道表示式(又称电子排布图)用方框代表轨道、箭头代表电子及自旋方向,能同时检验两条原理,如氮原子2p三个方框中各填一个同向箭头。\n**核心规律与结论**：由泡利原理得s、p、d、f能级最多容纳2、6、10、14个电子;由洪特规则得等价轨道“先分占、后成对”。等价轨道全空、半满(p³、d⁵)或全满(p⁶、d¹⁰)时体系能量较低、较稳定,该稳定性规律正是Cr($3\\mathrm{d}^{5}4\\mathrm{s}^{1}$)、Cu($3\\mathrm{d}^{10}4\\mathrm{s}^{1}$)偏离构造原理的原因。由轨道表示式可直接数出未成对电子数,如N有3个、O有2个、Fe有4个、Cr有6个未成对电子。\n**方法与思路**：画轨道表示式:先排框(s一个、p三个、d五个),再按“先分占且自旋相同、后成对且自旋相反”依次填箭头;检验给定图的错误要看两条:同一方框内两个箭头同向→违反泡利原理;等价轨道能分占却提前成对→违反洪特规则。数未成对电子只需统计各轨道上单个箭头的个数。\n**常考题型与考法**：判断某原子轨道表示式的正误并指出其违反的原理;书写指定原子或简单离子的轨道表示式;由未成对电子数反推元素或核对元素(常与元素推断联考);判断“基态原子最外层p能级有2个未成对电子”等约束条件下元素的范围。\n**易错提示**：分占后成对属洪特规则,同一轨道内自旋相反属泡利原理,判断时要对号入座;p能级是三个并列方框,不能并成一格;洪特特例只适用于d、f等能量相近能级间的电子调整,不能泛化为“先排满4s”;半满、全满说法的对象要看清是p还是d能级;未成对电子数指单个箭头数,成对电子不计数。",
