      "content": "**定义与核心概念**：电负性表示成键原子在化合物中吸引共用电子对能力的相对大小,常用Pauling标度,氟的电负性最大(规定为4.0)。同种原子间(如H₂、N₂、Cl₂)共用电子对不偏移,形成的共价键为非极性键;不同原子间电子对向电负性较大的原子一方偏移,形成极性键,偏移程度随电负性差增大而增大。分子中正、负电荷中心不重合的为极性分子,重合的为非极性分子。\n**核心规律与结论**：电负性的主要应用:①判断键型——两原子电负性差值大(经验界限约1.7)易形成离子键,差值小易形成共价键,如Na与Cl差值大生成离子键,Al与Cl差值较小,AlCl₃是共价化合物;②判断键的极性强弱与共用电子对的偏移方向。分子极性判断:双原子分子看键型——同核双原子分子(H₂、N₂、O₂)为非极性分子,异核双原子(HCl、CO)为极性分子;多原子分子看空间构型——直线形CO₂、平面三角形BF₃、正四面体CH₄与CCl₄等对称构型中,各极性键的极性相互抵消,是非极性分子;V形分子(H₂O、SO₂)、三角锥形分子(NH₃)以及配体不完全相同的分子(如CHCl₃)电荷中心不重合,是极性分子。\n**方法与思路**：判断分子极性按三步:①用VSEPR与杂化知识判断中心原子杂化和空间构型;②看中心原子有无孤对电子、各配体是否相同;③把各键极性当作矢量,判断能否抵消。常见快捷结论:中心原子无孤对、配体全部相同且构型对称→非极性分子;中心原子有孤对(三角锥、V形)或配体不同→极性分子。解释溶解性时用“相似相溶”经验规律。\n**常考题型与考法**：判断具体物质的分子极性(CO₂、SO₂、BF₃、NH₃、H₂O、CCl₄、CHCl₃、P₄等);辨析“含极性键的分子一定是极性分子”“非极性分子中一定不含极性键”等说法;用相似相溶解释I₂易溶于CCl₄而难溶于水、NH₃极易溶于水等现象;电负性用于判断键型与键的极性偏移方向。\n**易错提示**：键有极性不等于分子有极性——CO₂、BF₃、CH₄、CCl₄均含极性键却是非极性分子;键全为非极性则分子必为非极性(如H₂、N₂、P₄);判断分子极性前必须先会判断空间构型,不能只看分子式“对称”字样;电负性差1.7只是经验判据,存在例外(如HF的电负性差大于1.7却仍是共价化合物),不可绝对化。",
