      "content": "**定义与核心概念**：一个晶胞中含有的微粒数不能“看到几个算几个”,因为位于晶胞顶角、棱上、面上的微粒分别被多个晶胞共用,须用均摊法:立方晶胞中,顶角微粒的1/8、棱上微粒的1/4、面上微粒的1/2、体内的全部(1)属于该晶胞。常见晶胞的均摊结果:简单立方含1个原子;体心立方含2个($8\\times\\frac{1}{8}+1$);面心立方含4个($8\\times\\frac{1}{8}+6\\times\\frac{1}{2}$);NaCl晶胞含4个Na⁺与4个Cl⁻(即4个“NaCl”);CsCl晶胞含1个Cs⁺与1个Cl⁻;金刚石晶胞含8个C(顶角与面心共4个、体内4个);干冰晶胞中CO₂分子占据顶角与面心,含4个CO₂分子。\n**核心规律与结论**：设晶胞中含n个组成单元(对离子化合物取“化学式单元”,如NaCl取n=4),组成单元的摩尔质量为M,晶胞体积为V(立方体边长为a时$V=a^{3}$),则晶体密度$\\rho=\\frac{nM}{N_{A}V}$,即$M=\\rho\\cdotN_{A}\\cdotV/n$。式中晶胞参数a常用nm作单位,须换算:1nm=$10^{-9}$m=$10^{-7}$cm,密度$\\rho$用g·cm⁻³时,V必须用cm³。由密度与晶胞参数可求摩尔质量M或阿伏伽德罗常数$N_{A}$;由晶胞几何关系还可求最近微粒间距,如NaCl中相邻Na⁺与Cl⁻距离为$a/2$,CsCl中为$\\sqrt{3}a/2$(体对角线的一半),金刚石中最近C—C距离为$\\sqrt{3}a/4$。\n**方法与思路**：解题流程:①识图,确定晶胞类型与各微粒所在位置;②用均摊法数出各微粒数,并化成化学式单元数n;③列式$\\rho=\\frac{nM}{N_{A}a^{3}}$,代入数据前统一单位(边长nm换成cm);④求解目标量(密度、棱长、M或$N_{A}$),再用化学式验证合理性。\n**常考题型与考法**：给出晶胞结构图与晶胞参数、密度,求阿伏伽德罗常数、摩尔质量或晶胞棱长;NaCl、CsCl、金刚石、干冰及金属(体心、面心立方)晶胞是高频素材;常与“1mol金刚石含2molC—C键、1molSiO₂含4molSi—O键”等结构计数题组合考查。\n**易错提示**：均摊系数易记混:顶角1/8、棱上1/4、面上1/2、体内1;NaCl晶胞均摊得4个Na⁺与4个Cl⁻,取n=4,不要当成1个“NaCl”;单位换算是最大失分点,1nm=$10^{-7}$cm,不要误用$10^{-9}$;立方晶胞体积是$a^{3}$,密度公式中M用g·mol⁻¹时$\\rho$用g·cm⁻³才配套;金刚石晶胞体内还有4个C,不要只数顶角与面心。",
      "links": [
        "str-ionic",
        "str-crystal",
        "str-type"
      ],
      "note": "晶胞均摊与密度/阿伏伽德罗常数联算是结构题压轴高频计算,importance 5;因计算自成体系、较少被下游依赖,core 取 4。",
      "book": "选必2",
      "ch": "第3章 晶体结构与性质"
