      "note": "元素推断是原子结构与分子结构知识的综合应用型节点,自身很少被下游依赖故 core 2;与基础化学的周期表位置推断互补,本板块只用结构类条件。",
      "book": "拓展",
      "ch": "高考专题(教材无独立章节)"
