      "content": "**定义与核心概念**：燃烧热：101 kPa 时 1 mol 纯物质完全燃烧生成稳定氧化物时放出的热量。三个关键限定：可燃物为 1 mol、完全燃烧、生成稳定氧化物——C 生成 CO2(g)、H 生成 H2O(l)、S 生成 SO2(g)、N 生成 N2(g)。中和热：稀溶液中强酸与强碱反应生成 1 mol H2O(l) 时放出的热量。\n\n**核心公式与规律**：中和热 $\\Delta H=-57.3\\ \\mathrm{kJ\\cdot mol^{-1}}$，其实质为 $H^{+}(\\mathrm{aq})+OH^{-}(\\mathrm{aq})=H_{2}O(l)$。燃烧热示例：$\\mathrm{H_{2}}(g)+\\frac{1}{2}\\mathrm{O_{2}}(g)=\\mathrm{H_{2}O}(l)$，$\\Delta H=-285.8\\ \\mathrm{kJ\\cdot mol^{-1}}$。注意 mol 的基准：燃烧热指 1 mol 可燃物，中和热指生成 1 mol 液态水。中和热测定原理：$Q=c\\cdot m\\cdot\\Delta t$，$\\Delta H=-Q/n(H_{2}O)$。\n\n**方法与思路**：用燃烧热求反应热：$\\Delta H=\\sum\\Delta H_{燃烧}(反应物)-\\sum\\Delta H_{燃烧}(生成物)$（与盖斯定律同源）。中和热实验的关键是保温隔热、用环形玻璃搅拌棒充分搅拌并及时读数；用弱酸弱碱（电离吸热）或浓硫酸（稀释放热）都会使测得热量偏离 57.3 kJ，不能作为中和热数据。\n\n**常考题型与考法**：①概念辨析选择题（1 mol、完全燃烧、稳定氧化物、液态水等设错点）；②由燃烧热求反应热或比较燃料热值（单位质量放热）选择燃料；③中和热测定实验的装置与误差分析；④以燃烧热数据作为盖斯计算的已知量。\n\n**易错提示**：氢的稳定氧化物是液态水，写成 H2O(g) 即错；题目给 2 mol H2 完全燃烧放出 571.6 kJ 时，其燃烧热仍为 -285.8 kJ/mol（须折算成 1 mol）；中和热要求稀溶液、强酸强碱、生成 1 mol 液态水；回答放出多少热量不带负号，写 $\\Delta H$ 必须带负号。",
