      "content": "**定义与核心概念**：羟基直接连在苯环上的化合物叫酚，苯酚是最简单的酚：无色晶体、有特殊气味，露置空气会因氧化而变粉红；常温微溶于水（高于 65 ℃ 可与水互溶），有毒、有腐蚀性，俗名石炭酸。苯酚中苯环与羟基相互影响：苯环使羟基的氢变活泼而显弱酸性，羟基又使苯环邻、对位活化而更易发生取代。\n**核心结构与反应**：①弱酸性：苯酚能与 NaOH 反应生成苯酚钠；能与 Na2CO3 反应但只生成 NaHCO3（不放出 CO2）；苯酚钠溶液中通入 CO2 也只生成 NaHCO3 与苯酚，体现酸性顺序 CH3COOH＞H2CO3＞C6H5OH＞HCO3－②与钠：$\\mathrm{2C_{6}H_{5}OH+2Na\\rightarrow 2C_{6}H_{5}ONa+H_{2}\\uparrow}$，比乙醇与钠反应剧烈。③取代（苯环活化）：苯酚与浓溴水常温取代生成 2,4,6-三溴苯酚 C6H2Br3OH 白色沉淀，无需催化剂，可用于检验苯酚；对比：苯的溴代需液溴与 FeBr3 催化。④显色：遇 FeCl3 溶液显紫色。苯酚与甲醛还能缩聚得酚醛树脂（见高分子节点）。\n**方法与思路**：按“醇—酚—羧酸”比较羟基活性：乙醇不与 NaOH 反应，苯酚能与 NaOH、Na2CO3 反应但不能与 NaHCO3 反应，乙酸能与 NaHCO3 反应放出 CO2——用 NaHCO3 检验羧基、用 FeCl3 或浓溴水检验酚羟基。分离苯与苯酚：加 NaOH 使苯酚成盐入水层，分液后通 CO2 回收苯酚。\n**常考题型与考法**：苯酚与 Na2CO3、NaHCO3、CO2、NaOH 反应产物的判断；浓溴水沉淀与苯的液溴取代条件对比；FeCl3 显色检验；分子式为 C7H8O 且遇 FeCl3 显紫色的异构体有邻、间、对甲苯酚 3 种。\n**易错提示**：①苯酚钠溶液中通 CO2，无论过量与否都生成 NaHCO3，不生成 Na2CO3；②苯酚＋Na2CO3 不放出 CO2（生成 NaHCO3），说明其酸性弱于碳酸；③苯酚不能使石蕊变红、不与 NaHCO3 反应；④苯酚与浓溴水取代不需催化剂，苯的溴代需 FeBr3 且用液溴；⑤苯酚沾到皮肤应立即用酒精洗涤，不能泡在 NaOH 里（腐蚀性更强）。",
