      "content": "**定义与核心概念**：醛基（－CHO）位于碳链末端，连烃基或氢的化合物叫醛，饱和一元醛通式 CnH2nO；羰基连两个烃基的化合物叫酮（如丙酮 CH3COCH3，常用有机溶剂）。乙醛是无色、有刺激性气味的液体，易挥发、易溶于水；甲醛 HCHO 常温为气体，其水溶液福尔马林用于消毒防腐。醛基既有不饱和性（可加成）又有强还原性（易被氧化），是“既能被氧化又能被还原”的官能团。\n**核心结构与反应**：①银镜反应：乙醛与银氨溶液（AgNO3 中滴加稀氨水至沉淀恰好溶解，现配现用）水浴加热，试管内壁析出光亮银镜：$\\mathrm{CH_{3}CHO+2[Ag(NH_{3})_{2}]OH\\xrightarrow{\\text{水浴}}CH_{3}COONH_{4}+2Ag\\downarrow +3NH_{3}+H_{2}O}$。②与新制 Cu(OH)2：在 NaOH 过量的碱性条件下加热至沸腾，生成砖红色 Cu2O 沉淀（乙醛被氧化为乙酸钠）。③催化氧化：乙醛与 O2 在催化剂作用下氧化成乙酸。④还原（加氢）：乙醛与 H2 在 Ni 催化下生成乙醇（醛成伯醇、酮成仲醇）。酮不含醛基，不银镜、不与新制 Cu(OH)2 生成砖红色沉淀，可用于鉴别。\n**方法与思路**：检验醛基用银氨溶液（水浴）或新制 Cu(OH)2（加热煮沸），试剂都须新制并保持碱性。计量规律：1 mol 醛基最多还原出 2 mol Ag；甲醛 HCHO 相当于两个醛基，1 mol 甲醛最多生成 4 mol Ag。甲酸、甲酸酯、葡萄糖等含醛基或甲酰基的物质也能银镜。\n**常考题型与考法**：银镜与 Cu(OH)2 反应的条件辨析（水浴还是煮沸、碱的来源）；推断题“能发生银镜反应”作为官能团线索反推结构；由生成 Ag 的物质的量求醛的物质的量或醛基数。\n**易错提示**：①银氨溶液与新制 Cu(OH)2 必须新制，银镜要水浴加热，Cu2O 要加热至沸腾；②银镜反应中乙醛被氧化成乙酸并被氨中和为乙酸铵，Cu(OH)2 反应中被 NaOH 中和为乙酸钠，产物按教材方程式书写，不写游离乙酸；③加氢是还原反应，不能说乙醛“被氧化”；④酮不银镜、不与新制 Cu(OH)2 反应；",
      "links": [
        "org-classify",
        "org-alcohol",
        "org-acid",
        "org-sugar",
        "org-synthesis",
        "org-geometry"
      ],
      "note": "醛既能被氧化（银镜、新制氢氧化铜）又能被还原（加氢）；酮无醛基，是醛的鉴别对照。",
      "book": "选必3",
