      "content": "**定义与核心概念**：氨基酸是羧酸分子中烃基上的氢被氨基（－NH2）取代的产物，构成蛋白质的天然氨基酸都是 α-氨基酸（氨基与羧基连在同一碳上），通式可写 H2NCH(R)COOH，最简单的甘氨酸为 H2NCH2COOH。氨基酸分子中氨基与羧基并存，具有两性：既能与盐酸等酸成盐，也能与 NaOH 等碱成盐。氨基酸通过脱水缩合形成肽键（－CONH－，即酰胺键）：两个氨基酸缩合成二肽，多个缩合形成多肽与蛋白质；蛋白质是氨基酸经肽键连接而成的天然有机高分子，水解的最终产物是 α-氨基酸。核酸由核苷酸聚合而成。\n**核心结构与反应**：蛋白质的主要性质：①两性（肽链两端仍保留游离氨基与羧基）。②盐析：加入浓的轻金属盐溶液（如饱和 (NH4)2SO4 溶液），蛋白质因溶解度降低而析出，加水又能溶解——盐析可逆、不改变蛋白质结构与活性，常用于分离提纯。③变性：受加热、紫外线、强酸强碱、重金属盐（如 CuSO4）、甲醛、酒精作用，蛋白质空间结构被破坏、失去活性且不可逆——医疗消毒利用变性，重金属盐中毒可服牛奶、蛋清急救。④颜色反应：含苯环的蛋白质遇浓硝酸变黄。⑤灼烧有烧焦羽毛气味，可鉴别羊毛、蚕丝（蛋白质）与棉麻（纤维素）。\n**方法与思路**：对比：盐析（轻金属盐浓溶液、可逆、物理过程）用于提纯；变性（高温、重金属盐、甲醛等、不可逆）使蛋白质失活。写缩合方程式时一分子氨基酸脱羧基中的羟基、另一分子脱氨基中的一个氢，生成一分子水；水解则在肽键处加 H2O 拆开。\n**常考题型与考法**：盐析与变性的条件辨析（给操作判断类型）；灼烧气味鉴别织物成分；蛋白质水解最终产物；氨基酸两性（既与酸又与碱反应）；对比实验：加饱和 (NH4)2SO4 析出后加水溶解（盐析），加 CuSO4 析出后加水不溶解（变性）；二肽形成的基本书写。\n**易错提示**：①饱和 (NH4)2SO4、Na2SO4 使蛋白质盐析（可逆），CuSO4、铅盐等重金属盐使蛋白质变性（不可逆），都会析出沉淀但本质不同；②福尔马林（甲醛溶液）使蛋白质变性，只能用于标本防腐，不能用于食品；③灼烧烧焦羽毛气味是蛋白质特征；④氨基酸两性源于氨基与羧基并存，别只记碱性或只记酸性；⑤盐析不改变蛋白质分子结构，变性破坏空间结构。",
      "links": [
        "org-acid",
        "org-sugar",
        "org-fat",
        "org-polymer"
      ],
      "note": "氨基酸两性来自氨基与羧基；盐析可逆可提纯、变性不可逆用于消毒，二者条件与本质要分清。",
      "book": "选必3",
      "ch": "第4章 生物大分子"
