      "content": "**定义与核心概念**：算粒子数先明确微粒构成：由分子构成的物质先定分子数，再看每分子含多少原子；稀有气体是单原子分子，标准状况下 22.4 L 氖气含 $N_{A}$ 个原子；臭氧分子含 3 个氧原子；白磷以 $\\mathrm{P_{4}}$ 形式存在，每摩尔含 4 mol 磷原子、6 mol 磷磷键；离子化合物按“化学式单元”数离子，如每摩尔 $\\mathrm{Na_{2}O_{2}}$ 含 2 mol 钠离子与 1 mol 过氧根离子，离子共 3 mol。\n\n**核心规律与方法**：电子、质子、中子数按原子结构累加：水分子含 10 个质子、10 个电子、8 个中子；甲烷、氨、水、氖均为 10 电子微粒，铵根、氢氧根也各含 10 个电子（阳离子减电荷、阴离子加电荷）。同位素只改中子与质量：$\\mathrm{D_{2}O}$ 每摩尔含 10 mol 中子，$^{18}\\mathrm{O_{2}}$ 每摩尔含 20 mol 中子。质量相等的氧气与臭氧含氧原子数相同；氯化钠晶体中无分子，58.5 g 氯化钠含 $N_{A}$ 个钠离子与 $N_{A}$ 个氯离子。\n\n**方法与思路**：固定程序：写出化学式并判断结构类型→求每个“化学式单元”的目标粒子数→乘以物质的量。遇同位素或陌生物质先用 $n=m/M$ 求 $n$ 再换算；比较类选项（同质量、同分子数）先化为同一物理量再判断。\n\n**常考题型与考法**：选项素材集中：标况 22.4 L 氖或甲烷的原子数、质子数；1 mol 甲烷含 10 mol 质子；过氧化钠与氧化钠的离子总数、阴阳离子个数比；白磷、臭氧的原子数及同质量氧单质的原子数比较；重水、$^{18}\\mathrm{O_{2}}$ 的摩尔质量与中子数；10 电子微粒计数等，均属“微粒构成＋NA”综合判断。\n\n**易错提示**：氖等稀有气体勿按双原子分子算原子数；臭氧、白磷按实际分子组成算；重水、$^{18}\\mathrm{O_{2}}$ 的摩尔质量为 20、36 g/mol，勿与普通水、氧气混淆；过氧化钠的阴离子是整体过氧根离子，每摩尔还含 1 mol 氧氧键；离子化合物中无分子，不能说含 $N_{A}$ 个“氯化钠分子”；中子数等于质量数减质子数。",
