      "content": "**定义与核心概念**：NA 题本质是“条件与概念判断题”：把每个选项都化为“已知量→物质的量 $n$→目标粒子数”一条链，逐环核验。任何说法最终都落到 $n=\\frac{m}{M}$、标况气体 $n=\\frac{V}{22.4\\ \\mathrm{L\\cdot mol^{-1}}}$ 或 $n=cV$ 是否成立，因此不需要复杂计算，关键是条件识别与对象定位。\n\n**核心规律与方法**：三步程序：①算 $n$：质量路径注意 $\\mathrm{D_{2}O}$、$^{18}\\mathrm{O_{2}}$ 等特殊摩尔质量；气体路径只认“标况＋气态”；溶液路径浓度与体积缺一不可；②定对象：问的是分子、原子、离子、电子、质子、中子还是转移电子、化学键，换算因子各不相同（如每摩尔 $\\mathrm{CH_{4}}$ 含 5 mol 原子、10 mol 质子）；③乘 $N_{A}$ 比对选项，严防“每摩尔”与“每个分子”的换算错位。\n\n**方法与思路**：先做关键词扫描：出现“常温常压、非标况、未给体积、可逆、弱电解质、水解、胶体”等字眼的多为陷阱项，“等于 $N_{A}$”的说法往往错误；拿不准的选项回到公式定量核算。日常积累速查表：双原子分子、稀有气体单原子、10 电子微粒、$\\mathrm{P_{4}}$、过氧化钠构成等，可显著提速；考场上先排除条件错误明显的选项，再对剩余项逐条核验。\n\n**常考题型与考法**：必考单选题，难度中等但区分度高；变体包括相同质量 $\\mathrm{O_{2}}$ 与 $\\mathrm{O_{3}}$ 的比较、转移电子数比较等。备考按“陷阱清单＋速查表＋限时训练”进行，考场上对涉及可逆、电离、水解、胶粒的选项不必算到底，判定方向即可。\n\n**易错提示**：漏读“标准状况”或将 22.4 用于液体、固体；溶液题只给浓度未给体积；把胶粒数当成溶质粒子数；忽略可逆反应、弱电解质电离与盐类水解使粒子数减少；算转移电子数不标化合价变化而凭感觉估值；同位素物质的摩尔质量须按实际质量数计算；对离子晶体、原子晶体（如 $\\mathrm{NaCl}$、金刚石）不能用“分子数”表述。",
